using PickleballGenie.Models;

namespace PickleballGenie.Data;

/// <summary>
/// The single source of truth for the curated drill catalog. DbSeeder upserts
/// it by pinned Id on every API and Scraper startup: missing drills are
/// inserted and existing rows get their text and tags refreshed, so edit here,
/// never in the database. Ids are pinned to the a1000000-...-NNN sequence —
/// when adding drills, extend the sequence past the current maximum (120);
/// never renumber, reuse or delete an Id, and keep Titles unique.
///
/// Every drill carries:
/// - MinPlayers: 1 = solo (wall, ball machine, self-feed, shadow work),
///   2 = one partner or feeder, 4 = a doubles group. Every level has at least
///   eight solo drills, because the player who can't get a coach usually
///   can't get a drilling partner either.
/// - Equipment: comma-separated items from a fixed vocabulary — "Wall",
///   "Ball machine", "Bucket of balls", "Cones or targets" — or null.
/// - A Description in a fixed template (a one-sentence summary, then
///   "Setup:", "How to run it:", "Goal:" and "Coaching cue:" lines) that
///   clients split into sections and the LLM prompt flattens to one line.
///
/// Categories must be one of the ten strings used by the self-rating
/// feedback loop: Dinking, Drops, Volleys, Serving, Returns, Lobs, Resets,
/// Attacking, Movement, General.
/// </summary>
public static class CuratedDrills
{
    private const int Solo = 1;
    private const int Partner = 2;
    private const int Group = 4;

    private const string Wall = "Wall";
    private const string Machine = "Ball machine";
    private const string Bucket = "Bucket of balls";
    private const string Cones = "Cones or targets";

    private const string UsapaBasics = "https://usapickleball.org/what-is-pickleball/how-to-play/basics/";
    private const string UsapaRules = "https://usapickleball.org/what-is-pickleball/official-rules/";
    private const string KitchenDrills = "https://www.pickleballkitchen.com/drills/";
    private const string KitchenThirdShot = "https://pickleballkitchen.com/third-shot-drop/";
    private const string KitchenTransition = "https://pickleballkitchen.com/transition-zone/";
    private const string KitchenDinking = "https://pickleballkitchen.com/dinking-drills/";
    private const string KitchenAdvancedThird = "https://pickleballkitchen.com/advanced-third-shot/";
    private const string MaxDrills = "https://www.pickleballmax.com/category/drills/";
    private const string MaxSpeedUp = "https://pickleballmax.com/speed-up-drill/";
    private const string MaxErne = "https://pickleballmax.com/erne-drill/";
    private const string ThirdShotDrills = "https://3rdshotdrop.com/category/drills/";
    private const string ThirdShotReset = "https://3rdshotdrop.com/backhand-reset/";
    private const string ThirdShotDinking = "https://3rdshotdrop.com/competitive-dinking/";

    /// <summary>Builds one catalog entry so every drill shares the same Id scheme and description template.</summary>
    private static Drill D(
        int number, string title, string category, decimal level, int minutes, int minPlayers, string? equipment,
        string summary, string setup, string howTo, string goal, string cue, string sourceUrl) => new()
    {
        Id = Guid.Parse($"a1000000-0000-0000-0000-{number:D12}"),
        Title = title,
        Category = category,
        TargetDUPRLevel = level,
        EstimatedDurationMinutes = minutes,
        MinPlayers = minPlayers,
        Equipment = equipment,
        Description = $"{summary}\n\nSetup: {setup}\nHow to run it: {howTo}\nGoal: {goal}\nCoaching cue: {cue}",
        SourceUrl = sourceUrl,
    };

    // Factory method rather than a cached list: callers attach these instances
    // to different DbContexts, so each caller needs fresh untracked objects.
    public static List<Drill> GetAll() => new()
    {
        // ------------------------------------------------------------------
        // 2.0 — New to the game. Mostly solo: a wall, a bucket of balls and
        // an hour is the realistic training setup for a brand-new player.
